UNION ALL
SELECT gen_random_uuid(), id, 'example', jsonb_build_object('text', practice), jsonb_build_object('text', practice_id), difficulty, chapter, TRUE FROM inserted
UNION ALL
SELECT gen_random_uuid(), id, 'question', jsonb_build_object('type','multiple_choice','question','Which description best fits ' || term || '?','options',jsonb_build_array(definition,'A guaranteed trade result','A company earnings report','A tax calculation'),'answer',definition,'explanation',definition,'difficulty',difficulty,'parameters',jsonb_build_object()), jsonb_build_object('type','multiple_choice','question','Deskripsi mana yang paling sesuai untuk ' || term_id || '?','options',jsonb_build_array(definition_id,'Hasil transaksi yang dijamin','Laporan laba perusahaan','Perhitungan pajak'),'answer',definition_id,'explanation',definition_id,'difficulty',difficulty,'parameters',jsonb_build_object()), difficulty, chapter, TRUE FROM inserted
UNION ALL
SELECT gen_random_uuid(), id, 'question', jsonb_build_object('type','true_false','question',term || ' guarantees a profitable trade.','answer',FALSE,'explanation',practice,'difficulty',difficulty,'parameters',jsonb_build_object()), jsonb_build_object('type','true_false','question',term_id || ' menjamin transaksi yang menguntungkan.','answer',FALSE,'explanation',practice_id,'difficulty',difficulty,'parameters',jsonb_build_object()), difficulty, chapter, TRUE FROM inserted
UNION ALL
SELECT gen_random_uuid(), id, 'question', jsonb_build_object('type','multiple_choice','question','What is the safer learning habit here?','options',jsonb_build_array(practice,'Treat one chart as a guarantee','Copy a stranger''s trade','Use money needed for rent'),'answer',practice,'explanation','Charts are practice evidence, not guarantees.','difficulty',difficulty,'parameters',jsonb_build_object()), jsonb_build_object('type','multiple_choice','question','Kebiasaan belajar mana yang lebih aman?','options',jsonb_build_array(practice_id,'Menganggap satu grafik sebagai jaminan','Meniru transaksi orang asing','Memakai uang untuk kos'),'answer',practice_id,'explanation','Grafik adalah bukti latihan, bukan jaminan.','difficulty',difficulty,'parameters',jsonb_build_object()), difficulty, chapter, TRUE FROM inserted;

-- Visual chart-question variants for every Chapter 10/11 lesson. The data is fictional and deterministic.
INSERT INTO content_variants (id, lesson_id, variant_type, body, body_id, difficulty, topic_tag, is_active)
SELECT gen_random_uuid(), l.id, 'question',
  jsonb_build_object('type','chart_interpretation','question','Which practice option closes above its open?','chart',jsonb_build_array(jsonb_build_object('open',100,'high',112,'low',96,'close',108,'label','Context')),'options',jsonb_build_array(
    jsonb_build_object('id','up','label','Option A','chart',jsonb_build_array(jsonb_build_object('open',100,'high',112,'low',96,'close',108,'label','A'))),
    jsonb_build_object('id','down','label','Option B','chart',jsonb_build_array(jsonb_build_object('open',108,'high',112,'low',96,'close',100,'label','B'))),
    jsonb_build_object('id','flat','label','Option C','chart',jsonb_build_array(jsonb_build_object('open',104,'high',112,'low',96,'close',104,'label','C')))
  ),'answer','up','explanation','A close above the open is bullish for that practice candle; it is not a forecast.','difficulty',l.difficulty,'parameters',jsonb_build_object()),
  jsonb_build_object('type','chart_interpretation','question','Pilihan latihan mana yang ditutup di atas harga open?','chart',jsonb_build_array(jsonb_build_object('open',100,'high',112,'low',96,'close',108,'label','Konteks')),'options',jsonb_build_array(
    jsonb_build_object('id','up','label','Pilihan A','chart',jsonb_build_array(jsonb_build_object('open',100,'high',112,'low',96,'close',108,'label','A'))),
    jsonb_build_object('id','down','label','Pilihan B','chart',jsonb_build_array(jsonb_build_object('open',108,'high',112,'low',96,'close',100,'label','B'))),
    jsonb_build_object('id','flat','label','Pilihan C','chart',jsonb_build_array(jsonb_build_object('open',104,'high',112,'low',96,'close',104,'label','C')))
  ),'answer','up','explanation','Close di atas open berarti bullish untuk candle latihan tersebut; ini bukan ramalan.','difficulty',l.difficulty,'parameters',jsonb_build_object()),
  l.difficulty, t.chapter, TRUE
FROM lessons l JOIN topics t ON t.id = l.topic_id
WHERE t.chapter IN ('Reading Trading Charts','Decision Analysis Lab')
  AND NOT EXISTS (SELECT 1 FROM content_variants cv WHERE cv.lesson_id = l.id AND cv.variant_type = 'question' AND cv.body->>'type' = 'chart_interpretation');

